import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gelu_forward_kernel(const float* x, float* out, int num_elements) {
    const float sqrt_2_over_pi = sqrtf(2.0f / M_PI);
    const float kAlpha = 0.044715f;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x_val = x[idx];
        float x_cubed = x_val * x_val * x_val;
        float inner = sqrt_2_over_pi * (x_val + kAlpha * x_cubed);
        out[idx] = 0.5f * x_val * (1.0f + tanhf(inner));
    }
}

torch::Tensor gelu_forward_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int num_elements = x.numel();

    const int threads_per_block = 256;
    int num_blocks = (num_elements + threads_per_block - 1) / threads_per_block;

    gelu_forward_kernel<<<num_blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        num_elements
    );

    return out;
}
"""

gelu_cpp_source = "torch::Tensor gelu_forward_cuda(torch::Tensor x);"

gelu_extension = load_inline(
    name="gelu_extension",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_kernel_source,
    functions=["gelu_forward_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.gelu_forward = gelu_extension.gelu_forward_cuda

    def forward(self, x):
        return self.gelu_forward(x)
